def row_fill(inp, pred=None):
    out=[r[:] for r in inp]
    H,W=len(inp),len(inp[0])
    for i,row in enumerate(inp):
        known=[(j,v) for j,v in enumerate(row) if v!=0]
        if not known: continue
        # find smallest period p (1..W) consistent with known cells (cyclically not needed; just equality when both known)
        best=None
        for p in range(1,W+1):
            ok=True
            for j,v in known:
                # anchor: value determined by j mod p relative to first known
                pass
            # determine mapping j%p -> v
            mp={}
            for j,v in known:
                k=j%p
                if k in mp and mp[k]!=v: ok=False;break
                mp[k]=v
            if ok: best=(p,mp);break
        if best is None: 
            print('row',i,'no period');continue
        p,mp=best
        for j in range(W):
            if out[i][j]==0 and j%p in mp:
                out[i][j]=mp[j%p]
    return out
